 "content": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Find the largest monochrome 4-connected component, the patterned object.
    seen=set(); best=[]; color=bg
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v==bg or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); comp=[]
            while q:
                y,x=q.pop(); comp.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==v:
